  "mnemonics": [
    {
      "id": "mn-alarme",
      "label": "ALARME",
      "intro": "Signes d'alarme imposant une endoscopie",
      "entries": [
        {
          "key": "A",
          "term": "Amaigrissement inexpliqué."
        },
        {
          "key": "L",
          "term": "Loss of appetite — anorexie durable."
        },
        {
          "key": "A",
          "term": "Anémie ferriprive inexpliquée."
        },
        {
          "key": "R",
          "term": "Reflux ou dyspepsie qui change chez un patient de plus de 45-50 ans."
        },
        {
